    def minWindow(self, s1, s2):
        m, n = len(s1), len(s2)
        dp = [[-1]*n for _ in range(m)]
        for i in range(m):
            if s1[i] == s2[0]: dp[i][0] = i
            elif i > 0: dp[i][0] = dp[i-1][0]
        for j in range(1, n):
            for i in range(1, m):
                if s1[i] == s2[j]: dp[i][j] = dp[i-1][j-1]
                else: dp[i][j] = dp[i-1][j]
        start, length = -1, m+1
        for i in range(m):
            if dp[i][n-1] >= 0:
                l = i - dp[i][n-1] + 1
                if l < length: length = l; start = dp[i][n-1]
        return '' if start == -1 else s1[start:start+length]

