class Solution:
    def evaluate(self, expression):
        def parse(expr, scope):
            if expr[0] != '(':
                return int(expr) if expr.lstrip('-').isdigit() else scope[expr]
            expr = expr[1:-1]
            tokens = tokenize(expr)
            if tokens[0] == 'let':
                ns = dict(scope)
                i = 1
                while i < len(tokens)-1:
                    ns[tokens[i]] = parse(tokens[i+1], ns); i += 2
                return parse(tokens[-1], ns)
            elif tokens[0] == 'add':
                return parse(tokens[1], scope) + parse(tokens[2], scope)
            else:
                return parse(tokens[1], scope) * parse(tokens[2], scope)
        def tokenize(expr):
            tokens, i, n = [], 0, len(expr)
            while i < n:
                if expr[i] == ' ': i += 1
                elif expr[i] == '(':
                    d, j = 1, i+1
                    while d > 0:
                        if expr[j]=='(': d+=1
                        elif expr[j]==')': d-=1
                        j += 1
                    tokens.append(expr[i:j]); i = j
                else:
                    j = i
                    while j < n and expr[j] != ' ': j += 1
                    tokens.append(expr[i:j]); i = j
            return tokens
        return parse(expression, {})

