class Solution:
    def findClosestLeaf(self, root, k):
        from collections import defaultdict, deque
        graph = defaultdict(list)
        leaves = set()
        def build(node, par):
            if not node: return
            if not node.left and not node.right: leaves.add(node.val)
            if par:
                graph[node.val].append(par.val)
                graph[par.val].append(node.val)
            build(node.left, node); build(node.right, node)
        build(root, None)
        q, seen = deque([k]), {k}
        while q:
            cur = q.popleft()
            if cur in leaves: return cur
            for nb in graph[cur]:
                if nb not in seen: seen.add(nb); q.append(nb)
        return k

class Solution:
    def networkDelayTime(self, times, n, k):
        import heapq
        from collections import defaultdict
        graph = defaultdict(list)
        for u,v,w in times: graph[u].append((v,w))
        dist = {}
        heap = [(0, k)]
        while heap:
            d, u = heapq.heappop(heap)
            if u in dist: continue
            dist[u] = d
            for v, w in graph[u]:
                if v not in dist: heapq.heappush(heap, (d+w, v))
        return max(dist.values()) if len(dist)==n else -1

