class Solution:
    def ipToCIDR(self, ip, n):
        def ip2int(ip):
            parts = list(map(int, ip.split('.')))
            return (parts[0]<<24)+(parts[1]<<16)+(parts[2]<<8)+parts[3]
        def int2ip(x):
            return f'{(x>>24)&255}.{(x>>16)&255}.{(x>>8)&255}.{x&255}'
        start = ip2int(ip)
        res = []
        while n > 0:
            lowbit = start & (-start) if start else (1<<32)
            while lowbit > n: lowbit >>= 1
            mask = 32 - lowbit.bit_length() + 1
            res.append(f'{int2ip(start)}/{mask}')
            start += lowbit; n -= lowbit
        return res

