class Solution:
    def reorganizeString(self, s):
        from collections import Counter
        import heapq
        cnt = Counter(s)
        if max(cnt.values()) > (len(s)+1)//2: return ''
        heap = [(-v, k) for k, v in cnt.items()]
        heapq.heapify(heap)
        res = []
        while len(heap) >= 2:
            c1, ch1 = heapq.heappop(heap)
            c2, ch2 = heapq.heappop(heap)
            res += [ch1, ch2]
            if c1+1 < 0: heapq.heappush(heap, (c1+1, ch1))
            if c2+1 < 0: heapq.heappush(heap, (c2+1, ch2))
        if heap: res.append(heap[0][1])
        return ''.join(res)

