        class Poly:
            def __init__(self, terms=None):
                self.terms = terms or Counter()
            def __add__(self, o):
                r = Poly(Counter(self.terms)); 
                for k,v in o.terms.items(): r.terms[k]+=v
                return r
            def __sub__(self, o):
                r = Poly(Counter(self.terms))
                for k,v in o.terms.items(): r.terms[k]-=v
                return r
            def __mul__(self, o):
                r = Poly()
                for k1,v1 in self.terms.items():
                    for k2,v2 in o.terms.items():
                        key = tuple(sorted(k1+k2))
                        r.terms[key] += v1*v2
                return r
        def to_poly(token):
            if token in env: return Poly({(): env[token]})
            if token.lstrip('-').isdigit(): return Poly({(): int(token)})
            return Poly({(token,): 1})
        # Simple recursive descent parser
        tokens = []; i = 0
        while i < len(expression):
            if expression[i] == ' ': i+=1; continue
            if expression[i] in '()+*-':
                tokens.append(expression[i]); i+=1
            else:
                j=i
                while j<len(expression) and expression[j] not in ' ()+*-': j+=1
                tokens.append(expression[i:j]); i=j
        pos = [0]
        def expr():
            result = term()
            while pos[0]<len(tokens) and tokens[pos[0]] in '+-':
                op=tokens[pos[0]]; pos[0]+=1
                t=term()
                result = result+t if op=='+' else result-t
            return result
        def term():
            result = factor()
            while pos[0]<len(tokens) and tokens[pos[0]]=='*':
                pos[0]+=1; result=result*factor()
            return result
        def factor():
            if tokens[pos[0]]=='(':
                pos[0]+=1; r=expr(); pos[0]+=1; return r
            t=tokens[pos[0]]; pos[0]+=1
            return to_poly(t)
        poly = expr()
        res = []
        for k in sorted(poly.terms.keys(), key=lambda x: (-len(x), x)):
            v = poly.terms[k]
            if v == 0: continue
            term_str = str(v) + ('*'+'*'.join(k) if k else '')
            res.append(term_str)
        return res

class Solution:
    def numJewelsInStones(self, jewels, stones):
        j = set(jewels)
        return sum(s in j for s in stones)

class Solution:
    def calculate(self, s):
        s = s.replace(' ', '')
        pos = [0]
        def expr():
            result = term()
            while pos[0] < len(s) and s[pos[0]] in '+-':
                op = s[pos[0]]; pos[0] += 1
                t = term()
                result = result+t if op=='+' else result-t
            return result
        def term():
            result = factor()
            while pos[0] < len(s) and s[pos[0]] in '*/':
                op = s[pos[0]]; pos[0] += 1
                f = factor()
                result = result*f if op=='*' else int(result/f)
            return result
        def factor():
            if s[pos[0]] == '(':
                pos[0] += 1; r = expr(); pos[0] += 1; return r
            j = pos[0]
            if s[j] in '+-': j += 1
            while j < len(s) and s[j].isdigit(): j += 1
            r = int(s[pos[0]:j]); pos[0] = j; return r
        return expr()

class Solution:
    def slidingPuzzle(self, board):
        from collections import deque
        start = ''.join(str(x) for row in board for x in row)
        target = '123450'
        if start == target: return 0
        neighbors = {0:[1,3],1:[0,2,4],2:[1,5],3:[0,4],4:[1,3,5],5:[2,4]}
        q = deque([(start, 0)])
        visited = {start}
        while q:
            state, steps = q.popleft()
            zi = state.index('0')
            for ni in neighbors[zi]:
                ns = list(state)
                ns[zi], ns[ni] = ns[ni], ns[zi]
                ns = ''.join(ns)
                if ns == target: return steps+1
                if ns not in visited:
                    visited.add(ns); q.append((ns, steps+1))
        return -1

class Solution:
    def minmaxGasDist(self, stations, k):
        lo, hi = 0, stations[-1]-stations[0]
        while hi-lo > 1e-6:
            mid = (lo+hi)/2
            cnt = sum(int((stations[i+1]-stations[i])/mid) for i in range(len(stations)-1))
            if cnt <= k: hi = mid
            else: lo = mid
        return hi

class Solution:
    def isIdealPermutation(self, nums):
        mx = 0
        for i in range(2, len(nums)):
            mx = max(mx, nums[i-2])
            if mx > nums[i]: return False
        return True

class Solution:
    def splitBST(self, root, target):
        if not root: return [None, None]
        if root.val <= target:
            left, right = self.splitBST(root.right, target)
            root.right = left
            return [root, right]
        else:
            left, right = self.splitBST(root.left, target)
            root.left = right
            return [left, root]

class Solution:
    def swimInWater(self, grid):
        import heapq
        n = len(grid)
        heap = [(grid[0][0], 0, 0)]
        visited = [[False]*n for _ in range(n)]
        visited[0][0] = True
        while heap:
            t, r, c = heapq.heappop(heap)
            if r == n-1 and c == n-1: return t
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0<=nr<n and 0<=nc<n and not visited[nr][nc]:
                    visited[nr][nc] = True
                    heapq.heappush(heap, (max(t, grid[nr][nc]), nr, nc))
        return -1

class Solution:
    def kthGrammar(self, n, k):
        if n == 1: return 0
        parent = self.kthGrammar(n-1, (k+1)//2)
        if k % 2 == 1: return parent
        return 1 - parent

class Solution:
    def reachingPoints(self, sx, sy, tx, ty):
        while tx >= sx and ty >= sy:
            if tx == ty: break
            if tx > ty:
                if ty == sy: return (tx-sx) % ty == 0
                tx %= ty
            else:
                if tx == sx: return (ty-sy) % tx == 0
                ty %= tx
        return tx == sx and ty == sy
